// End-to-end conversion instrumentation
// Tracks view → checkout → paid flow

export const trackConversionStep = (userId, step, metadata = {}) => {
  // Log to data/conversion-events/
  console.log(`[CONVERSION] ${userId} - ${step}`, metadata);
  // Add analytics event
  analytics.track(`Checkout Conversion ${step}`, {
    ...metadata,
    timestamp: new Date().toISOString()
  });
};
